import base64
import sys

file_path = r'C:\Users\ASUS\Documents\abbk_pfe\dali-pfe\lib\client_dashboard_page.dart'
with open(file_path, 'r', encoding='utf-8') as f:
    lines = f.readlines()

b64_replacement = ','
replacement = base64.b64decode(b64_replacement).decode('utf-8')
replacement_lines = [line + '\n' for line in replacement.split('\n')]
replacement_lines[-1] = replacement_lines[-1].strip('\n') # remove last extra newline

# we replace from 1526 to 1547.
# Since lists are 0-indexed, 1526 in IDE is 1525 in list. 1547 is 1546.
lines = lines[:1526] + replacement_lines + lines[1547:]

with open(file_path, 'w', encoding='utf-8') as f:
    f.writelines(lines)
print('Done!')
